  if (owBirdState) return CT_NOT_ORACLE(runOwBirds(romPath, owBirdState, owBirdOut));
  if (owBalloonState) return CT_NOT_ORACLE(runOwBalloons(romPath, owBalloonState, owBalloonOut));
