  if (doSweepMulDiv) return CT_NOT_ORACLE(runSweepMulDiv(romPath));
  if (doSweepHitRoll) return CT_NOT_ORACLE(runSweepHitRoll(romPath));
  if (doSweepStatFetch) return CT_NOT_ORACLE(runSweepStatFetch(romPath));
